INSERT INTO `forever_writ_x` (`ID`,`RewardText`) VALUES
(94254,'My new robe! Delightful!$B$BAt long last, I can don my robe AND my wizard hat.'),
(94302,'My new home is surrounded by turtles, yet I have no knowledge of how to properly prepare their meat nor craft equipment with their scales.$B$BAs shameful as it feels, my survival has depended upon the aid of others outside my tribe. I have been humbled by the kindness of strangers, and humbled by the simple yet effective techniques they have taught me.$B$BI hope to learn from this turtle scale breastplate in much the same way.');
