-- WoW Forever: Craftsman's Writs, rare drops and quest fixes from Everlake's world data of 19 Nov.
-- From Everlake's world data (buildthehomelab/wow-everlake-world-data, main 0ffaa3d, GPL-3.0): its files 2026_11_19_936, 942-944
-- and 981-982, which take the quest records from EG Link (Efficient Games, CC BY 4.0, eg-link-output-wowf c389a87: the live
-- client's own quest data) and texts and drop counts from Wowhead's WoW Forever database (www.wowhead.com/forever). Not their
-- files: each row was checked against our world and written here as our own, only where ours lacks it. Safe to run more than once.

-- 1. Craftsman's Writs: 88 writ quests (a writ found in the world asks for one crafted item, delivered to an NPC for Forever
--    profession reputation and a treasure-picker reward). Only writs whose deliverer stands in our world and whose items the
--    client has (the other 6 writs go to NPCs our world does not have yet and are left out).
-- The writ quests (Craftsman's Writ: ...), as the live client's quest records give them.
DROP TEMPORARY TABLE IF EXISTS `forever_writ_q`;
CREATE TEMPORARY TABLE `forever_writ_q` SELECT `ID`,`RewardItem1`,`RewardAmount1`,`ItemDrop1`,`ItemDropQuantity1`,`RewardItem2`,`RewardAmount2`,`ItemDrop2`,`ItemDropQuantity2`,`RewardItem3`,`RewardAmount3`,`ItemDrop3`,`ItemDropQuantity3`,`RewardItem4`,`RewardAmount4`,`ItemDrop4`,`ItemDropQuantity4`,`RewardChoiceItemID1`,`RewardChoiceItemQuantity1`,`RewardChoiceItemID2`,`RewardChoiceItemQuantity2`,`RewardChoiceItemID3`,`RewardChoiceItemQuantity3`,`RewardChoiceItemID4`,`RewardChoiceItemQuantity4`,`RewardChoiceItemID5`,`RewardChoiceItemQuantity5`,`RewardChoiceItemID6`,`RewardChoiceItemQuantity6`,`RewardFactionID1`,`RewardFactionValue1`,`RewardFactionOverride1`,`RewardFactionCapIn1`,`RewardFactionID2`,`RewardFactionValue2`,`RewardFactionOverride2`,`RewardFactionCapIn2`,`RewardFactionID3`,`RewardFactionValue3`,`RewardFactionOverride3`,`RewardFactionCapIn3`,`RewardFactionID4`,`RewardFactionValue4`,`RewardFactionOverride4`,`RewardFactionCapIn4`,`RewardFactionID5`,`RewardFactionValue5`,`RewardFactionOverride5`,`RewardFactionCapIn5`,`RewardCurrencyID1`,`RewardCurrencyQty1`,`RewardCurrencyID2`,`RewardCurrencyQty2`,`RewardCurrencyID3`,`RewardCurrencyQty3`,`RewardCurrencyID4`,`RewardCurrencyQty4`,`QuestType`,`QuestInfoID`,`RewardNextQuest`,`StartItem`,`Flags`,`FlagsEx`,`FlagsEx2`,`TimeAllowed`,`QuestSortID`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardSpell`,`AllowableRaces`,`AcceptedSoundKitID`,`CompleteSoundKitID`,`Expansion`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog` FROM `quest_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_q`;

-- Their objectives: the writ itself and the crafted item it asks for.
DROP TEMPORARY TABLE IF EXISTS `forever_writ_o`;
CREATE TEMPORARY TABLE `forever_writ_o` SELECT `ID`,`QuestID`,`Type`,`Order`,`StorageIndex`,`ObjectID`,`Amount`,`Flags`,`Description` FROM `quest_objectives` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_o`;

DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;
CREATE TEMPORARY TABLE `forever_writ_x` SELECT `ID`,`QuestLevel`,`MinLevel`,`MaxLevel` FROM `quest_classic_level` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;

DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;
CREATE TEMPORARY TABLE `forever_writ_x` SELECT `ID`,`LevelType`,`QuestLevel` FROM `quest_template_classic_level` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;

DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;
CREATE TEMPORARY TABLE `forever_writ_x` SELECT `QuestID`,`TreasurePickerID`,`OrderIndex` FROM `quest_treasure_pickers` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;

DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;
CREATE TEMPORARY TABLE `forever_writ_x` SELECT `ID`,`RewardText` FROM `quest_offer_reward` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;

DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;
CREATE TEMPORARY TABLE `forever_writ_x` SELECT `ID`,`CompletionText` FROM `quest_request_items` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_x`;

-- Who takes the writ in: the NPC the delivery point names (spawned in our world).
DROP TEMPORARY TABLE IF EXISTS `forever_writ_e`;
CREATE TEMPORARY TABLE `forever_writ_e` SELECT `id`,`quest` FROM `creature_questender` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_e`;

UPDATE `creature_template` SET `npcflag`=`npcflag`|2 WHERE `entry` IN (10921,10922,10924,11019,11438,11536,11706,11795,11802,11805,11863,12024,12029,12959,13656,13717,14437,14470,14624,14628,14634,14743,15175,15194,2501,257281,257282,257304,257322,257429,257437,257743,257750,261932,261961,262016,262033,262143,262284,262306,262388,2663,2817,2888,3134,3536,4201,4496,4503,4706,5594,5598,5634,6176,6546,6548,6568,7363,7408,7801,8305,8379,8579,9116,9272,9273,9619) AND (`npcflag`&2)=0;

-- One writ is offered by an NPC rather than found.

-- 2. Turn-in progress texts for three quests that had none (Control Five Bases 8115, Take Four Bases 8121, The Keeper's Call
--    9247), as Wowhead's Forever pages show them. Only where the quest has no row yet.

-- 3. A Donation of Wool to the High Order (99191) and to the Windshapers (99196): handed in at once like the original game's
--    cloth donations (7791, 7792: QuestType 0, no giver's text). Only while they still have no giver's text.
UPDATE `quest_template` SET `QuestType`=0 WHERE `ID` IN (99191,99192,99196,99197) AND `QuestType`=2
  AND COALESCE(`QuestDescription`,'')='' AND COALESCE(`LogDescription`,'')='';

-- 4. Crown of the Earth (934) asks for the Filled Amethyst Phial (5646), made by filling the empty Amethyst Phial (5623) at the
--    moonwell, but nothing gave the empty phial. The quest hands it over on accept (as Wowhead Forever and VMaNGOS have it). Only
--    while the quest hands over nothing and asks for 5646.
UPDATE `quest_template` SET `StartItem`=5623 WHERE `ID`=934 AND `StartItem`=0
  AND EXISTS (SELECT 1 FROM `quest_objectives` WHERE `QuestID`=934 AND `Type`=1 AND `ObjectID`=5646);
UPDATE `quest_template_addon` SET `ProvidedItemCount`=1 WHERE `ID`=934 AND `ProvidedItemCount`=0
  AND EXISTS (SELECT 1 FROM `quest_template` WHERE `ID`=934 AND `StartItem`=5623);

-- 5. New Forever items that nothing in our world gave, on the one creature Wowhead's Forever item page names (mostly classic
--    rares: Kurmokk, Rippa, Jade, Mojo the Twisted, King Mosh, Deathmaw, Lord Maldazzar ...; and Pattern: Warbear Helm on
--    Eldreth Seether, 3 in 29 kills). Chance = drops / kills as Wowhead counted them (few kills on a rare). Only spawned
--    creatures and items the client has; a row goes in only where the creature's loot id is its own entry (or not set and
--    unused; then it is set), so no other creature's loot changes.
DROP TEMPORARY TABLE IF EXISTS `forever_drops_1119b`;
CREATE TEMPORARY TABLE `forever_drops_1119b` (`Entry` INT UNSIGNED NOT NULL, `Item` INT UNSIGNED NOT NULL, `Chance` FLOAT NOT NULL, `QuestRequired` TINYINT UNSIGNED NOT NULL, `MinCount` TINYINT UNSIGNED NOT NULL, `MaxCount` TINYINT UNSIGNED NOT NULL, PRIMARY KEY (`Entry`,`Item`));
UPDATE `creature_template_difficulty` `d` SET `d`.`LootID`=`d`.`Entry` WHERE `d`.`DifficultyID`=0 AND `d`.`LootID`=0
  AND `d`.`Entry` IN (SELECT `Entry` FROM `forever_drops_1119b`)
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` `l` WHERE `l`.`Entry`=`d`.`Entry`);
SELECT `s`.`Entry`,0,`s`.`Item`,`s`.`Chance`,`s`.`QuestRequired`,1,0,`s`.`MinCount`,`s`.`MaxCount`,'Everlake data: Wowhead Forever' FROM `forever_drops_1119b` `s`
JOIN `creature_template_difficulty` `d` ON `d`.`Entry`=`s`.`Entry` AND `d`.`DifficultyID`=0 AND `d`.`LootID`=`s`.`Entry`
WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` `x` WHERE `x`.`Entry`=`s`.`Entry` AND `x`.`ItemType`=0 AND `x`.`Item`=`s`.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `creature_template_difficulty` `o` WHERE `o`.`LootID`=`s`.`Entry` AND `o`.`Entry`<>`s`.`Entry`);
DROP TEMPORARY TABLE IF EXISTS `forever_drops_1119b`;

-- 6. The writs' world drops (one writ quest is also offered by an NPC).
-- One writ is offered by an NPC rather than found.
DROP TEMPORARY TABLE IF EXISTS `forever_writ_s`;
CREATE TEMPORARY TABLE `forever_writ_s` SELECT `id`,`quest` FROM `creature_queststarter` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_s`;

UPDATE `creature_template` SET `npcflag`=`npcflag`|2 WHERE `entry` IN (8379) AND (`npcflag`&2)=0;

-- Where writs come from. Wowhead's Forever writ guide (15 Nov) says writs are world drops suited to the zone's level, in three
-- tiers (Journeyman, Expert, Artisan; the quest records agree: treasure pickers 4817/4818/4819). No public recording names the
-- creatures or the rate, so these are set here (Everlake's choice, kept so both realms behave the same): one list per tier,
-- every writ of the tier equally likely; 0.5% per kill on every open-world creature with loot by its highest level:
-- Journeyman 20-34, Expert 35-51, Artisan 52-63. Reference loot 9500001-9500003 are new ids.
DROP TEMPORARY TABLE IF EXISTS `forever_writ_r`;
CREATE TEMPORARY TABLE `forever_writ_r` SELECT `Entry`,`ItemType`,`Item`,`Chance`,`QuestRequired`,`LootMode`,`GroupId`,`MinCount`,`MaxCount`,`Comment` FROM `reference_loot_template` WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `forever_writ_r`;

SELECT `g`.`LootID`,1,CASE WHEN `g`.`lv` BETWEEN 20 AND 34 THEN 9500001 WHEN `g`.`lv` BETWEEN 35 AND 51 THEN 9500002 ELSE 9500003 END,
  0.5,0,1,0,1,1,'Craftsman''s Writ world drop'
FROM (SELECT `d`.`LootID`, MAX(`l`.`level_max`) AS `lv`
  FROM `creature_template_difficulty` `d`
  JOIN `creature_template` `t` ON `t`.`entry`=`d`.`Entry`
  JOIN `creature_classic_level` `l` ON `l`.`entry`=`d`.`Entry`
  WHERE `d`.`DifficultyID`=0 AND `d`.`LootID`>0 AND `t`.`type`<>8
    AND EXISTS (SELECT 1 FROM `creature` `c` WHERE `c`.`id`=`d`.`Entry` AND `c`.`map` IN (0,1,2991))
  GROUP BY `d`.`LootID`) `g`
WHERE `g`.`lv` BETWEEN 20 AND 63
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` `x` WHERE `x`.`Entry`=`g`.`LootID` AND `x`.`ItemType`=1 AND `x`.`Item` IN (9500001,9500002,9500003));
